*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gConfmYn;
scwin.gMktCd;
scwin.gComNm;
scwin.colorCnt = 0; //조회한 이후에만 컬럼에  color 변경하기 위한 변수 

scwin.vScrenID = 'ULDSTF38600.xml';
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
}; //시장운영관련공시조회

// 시장구분 라디오버튼
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == "2" || scwin.gLdMktTp == "6") {
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        rdo_MKT_ID.setDisabled(true);
    } else {
        $c.cm.fn_com_isur_all(txb_ISUR_CD, txb_COM_NM);
        $c.stf.setObjectValue(rdo_MKT_ID, '2');
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.addClass("TopCondition_Blue");
    }
    chb_Type_A.setValue(1);
    chb_Type_1.setValue(1);
    chb_Type_2.setValue(1);
    chb_Type_3.setValue(1);
    chb_Type_4.setValue(1);
    chb_Type_5.setValue(1);
    chb_Type_6.setValue(1);
    chb_Type_7.setValue(1);
    chb_LIST_STAT_CD.setValue(0); //상장폐지여부
    //조회기간 셋팅
    $c.stf.setObjectValue(cmb_srcType, "A");
    scwin.fn_SetDate();
};


// 날짜
scwin.fn_SetDate = function() {
    //  기간 from~ to  셋팅(공시일자)
    var vTp = $c.cp.valueOfIndex(cmb_srcType, "VALUE", cmb_srcType.getSelectedIndex());
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vTp == "A") {
        //조치일
        edt_SDATE.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1));
        edt_EDATE.setValue('99991231');
        $c.stf.showObj(chk_lst_yn, false);
        $c.stf.showObj(lbl_lst_yn, false);
    } else {
        //공시일
        edt_SDATE.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1));
        edt_EDATE.setValue(vCurDate);
        $c.stf.showObj(chk_lst_yn, true);
        $c.stf.showObj(lbl_lst_yn, true);
    }
};



//조회 버튼
scwin.fn_Search = function() {
    scwin.colorCnt = 1; //조회를 클릭한 경우에만 컬럼 color 변경해줌

    var typeCnt = 0;
    var checkCnt = [chb_Type_1, chb_Type_2, chb_Type_3, chb_Type_4, chb_Type_5, chb_Type_6, chb_Type_7];
    for (var i = 0; i < checkCnt.length; i++) {
        if (scwin.getChkValue(checkCnt[i]) == "Y") {
            typeCnt++;
        }
    }
    if (typeCnt <= 0) {
        $c.win.alert("공시사유를 한개 이상 체크해야 합니다.");
    } else {
        $c.cm.ShowWin(grd_Grid);
        var url = "/MktOperDsclList.do?method=listMktOperDsclList";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD); //법인코드
        url += "&LIST_STAT_CD=" + $c.stf.getObjectValue(chb_LIST_STAT_CD); //상장폐지법인 제외
        url += "&LST_YN=" + $c.stf.getObjectValue(chk_lst_yn); //최종공시
        url += "&DATE_TYPE=" + $c.stf.getObjectValue(cmb_srcType); //조회구분
        url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE); //공시일자 from
        url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE); //공시일자 to			
        url += "&TYPEA_YN=" + scwin.getChkValue(chb_Type_A); //전체 
        url += "&TYPE1_YN=" + scwin.getChkValue(chb_Type_1); //유상증자
        url += "&TYPE2_YN=" + scwin.getChkValue(chb_Type_2); //무상증자
        url += "&TYPE3_YN=" + scwin.getChkValue(chb_Type_3); //주식배당
        url += "&TYPE4_YN=" + scwin.getChkValue(chb_Type_4); //액면변경
        url += "&TYPE5_YN=" + scwin.getChkValue(chb_Type_5); //자본감소
        url += "&TYPE6_YN=" + scwin.getChkValue(chb_Type_6); //인적분할
        url += "&TYPE7_YN=" + scwin.getChkValue(chb_Type_7); //신규상장
        url += "&TYPE_CNT=" + typeCnt;
        dts_Grid.DataID = encodeURI(url);
        dts_Grid.Reset();
    }
};
scwin.getChkValue = function(obj) {
    return (obj.checked) ? "Y" : "N";
};
scwin.fn_allCheck = function() {
    //체크박스
    var checkArray;
    checkArray = [chb_Type_A, chb_Type_1, chb_Type_2, chb_Type_3, chb_Type_4, chb_Type_5, chb_Type_6, chb_Type_7];
    if (chb_Type_A.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_Type_A.checked == false) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};




// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_Grid.getCellData(eval(obj), "ISUR_CD");
    scwin.gConfmYn = dts_Grid.getCellData(eval(obj), "CONFM_YN");
    scwin.gMktCd = $c.stf.getObjectValue(rdo_MKT_ID);
    scwin.gComNm = dts_Grid.getCellData(eval(obj), "COM_ABBRV");
};


/*function setGridHiddenColumnProp() {
		if(  chb_LIST_STAT_CD.checked  == true ) {
grd_Grid.setColumnProp("LIST_STAT_CD",'Show',false) ;
		} else {
grd_Grid.setColumnProp("LIST_STAT_CD",'Show',true) ;
		}
	}*/


scwin.chb_Type_A_onclick = function() {
    scwin.fn_allCheck();
};
scwin.chb_Type_1_onclick = function() {
    chb_Type_A.setValue(0);
};
scwin.chb_Type_2_onclick = function() {
    chb_Type_A.setValue(0);
};
scwin.chb_Type_3_onclick = function() {
    chb_Type_A.setValue(0);
};
scwin.chb_Type_4_onclick = function() {
    chb_Type_A.setValue(0);
};
scwin.chb_Type_5_onclick = function() {
    chb_Type_A.setValue(0);
};
scwin.chb_Type_6 = async function([object Object], [object Object]) {
    function chb_Type_7_onclick() {
        chb_Type_A.setValue(0);
    };

    function btn_Search_onclick() {
        scwin.fn_Search();
    };

    function txb_ISUR_CD_onkeyup() {
        if (txb_ISUR_CD.getValue() == "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode == 40) {
                //아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    };

    function txb_ISUR_CD_onfocus() {
        Grd_com_isur.style.display = "none";
    };

    function txb_ISUR_CD_onblur() {
        if (stFocusGrid == false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() == "") {
            txb_COM_NM.setValue("");
        }
    };

    function btn_ISUR_CD_onclick() {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

    };

    function Grd_com_isur_OnKeyPress(kcode) {
        if (kcode == '13') {
            $c.cm.fn_com_Confirm_set();
        }
    };

    function Grd_com_isur_OnDblClick(row, colid) {
        $c.cm.fn_com_Confirm_set();
    };

    function Grd_com_isur_OnClick(row, colid) {
        Grd_com_isur.style.display = "";
    };

    function Grd_com_isur_OnSetFocus() {
        stFocusGrid = true;
    };

    function Grd_com_isur_OnKillFocus() {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    };

    function btn_EDATE_onclick() {
        popUpCalendar2(edt_EDATE); //공시일자-시작일 이미지 버튼 클릭 시 달력 팝업

    };

    function btn_SDATE_onclick() {
        popUpCalendar2(edt_SDATE); //공시일자-종료일 이미지 버튼 클릭 시 달력 팝업

    };

    function grd_Grid_OnClick(row, colid) {
        // 클릭된 값 변수에 셋팅
        scwin.fn_setContnId(row);
        if (colid == "RSN_TP_CD") {
            $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R"); //(정정)공시일 컬럼 더블클릭시 관련 보고서 뷰잉

        } else if (colid == "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        } else if (colid == "CONFM_YN") {
            if (scwin.gConfmYn == "Y") {
                var url = "/dsclstat/ULDSTF25101.gfm?ISUR_CD=" + scwin.gIsurCd + "&MKT_CD=" + scwin.gMktCd + "&COM_NM=" + scwin.gComNm;
                var winTitle = "유상증자";
                if ($c.frame.path("/top") != undefined) {
                    $c.frame.path("/top").WinOpen("유상증자" + scwin.gIsurCd, url, winTitle, 1280, 770);
                } else {
                    await $c.frame.CreateDialogFrame("유상증자" + scwin.gIsurCd, url, winTitle, 10, 10, 1280, 770, "window");
                }
            }
        }
    };

    function dts_Grid_OnLoadError() {
        $c.cm.CloseWin('', grd_Grid); //조회완료시 LOADING 이미지 종료
        $c.win.alert(dts_Grid.errorMsg);
    };

    function dts_Grid_OnLoadCompleted(rowcount) {
        $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
        //setGridHiddenColumnProp();
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수

    };

    function btn_Excel_onclick() {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, "시장운영관련공시조회", "", "2"); //엑셀 다운로드

    };

    function btn_helpStr_onclick() {
        var url = "/dsclmgt/ULDSTF38601.gfm";
        await $c.frame.CreateDialogFrame("도움말" + scwin.gIsurCd, url, "시장운영 관련 공시 도움말", 10, 10, 830, 1040, "window");
        //frame.Provider("../../").GWinOpen("child01", url, "시장운영 관련 공시 도움말", 200, 10, 830, 1040, "");

    };

    function MxDataSet_com_isur_OnFilter(row) {
        if (skw != "" && foColum == "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

            else return false;
        } else {
            return true;
        }
    };

    function cmb_srcType_OnSelChange() {
        scwin.fn_SetDate();
    };

    function cmb_PeriodTp_OnSelChange() {
        var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
        $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE); //기간선택 콤보박스

    };

    function gform_onload() {
        Grd_com_isur.style.zIndex = 30;
        $c.libRoundPanel.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
        scwin.fn_Init(); //시장구분

    };
};
